import java.util.*;
import java.io.*;

public class HeightAllTheSame {
    private static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(reader.readLine());

        long N = Long.parseLong(st.nextToken());
        long M = Long.parseLong(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());

        long cells = N * M;
        long range = R - L + 1;
        long powered = pow(range, cells);

        if (cells % 2L == 1L) {
            writer.println(powered);
        } else if (range % 2L == 0L) {
            writer.println(powered * ((MOD + 1L) / 2L) % MOD);
        } else {
            writer.println((powered + 1L) * ((MOD + 1L) / 2L) % MOD);
        }

        reader.close();
        writer.close();
    }

    private static long pow(long base, long exponent) {
        if (exponent <= 0L) {
            return 1L;
        }
        long half = pow(base * base % MOD, exponent / 2L);
        if ((exponent & 1L) == 1L) {
            return half * base % MOD;
        }
        return half;
    }
}
